def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass."""
    class PointSubclass:
        def __init__(self, **kwargs):
            for field in fields:
                if field in kwargs:
                    setattr(self, field, kwargs[field])
                else:
                    setattr(self, field, None)

            if 'srid' in kwargs:
                self.srid = kwargs['srid']
            else:
                raise ValueError("SRID must be specified")

    for field in fields:
        PointSubclass.__annotations__[field] = type(None)

    PointSubclass.srid = type(None)

    if hasattr(srid_map, 'register'):
        srid_map.register(PointSubclass)

    return PointSubclass

