def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from functools import wraps
    from collections import OrderedDict
    from typing import Any, Callable

    class LFUCache:
        def __init__(self, maxsize: int, typed: bool) -> None:
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()
            self.access_count = {}
            self.keys = {}

        def __call__(self, func: Callable) -> Callable:
            @wraps(func)
            def wrapper(*args: Any, **kwargs: Any) -> Any:
                key = (func, args, frozenset(kwargs.items()) if typed else None)
                if key in self.cache:
                    self.access_count[key] += 1
                else:
                    self.access_count[key] = 1
                    while len(self.cache) >= self.maxsize:
                        lru_key, _ = self.cache.popitem(last=False)
                        self.access_count.pop(lru_key)
                        if lru_key in self.keys:
                            min_count = min(self.access_count[key] for key in self.keys[lru_key])
                            lru_keys = [k for k in self.keys[lru_key] if self.access_count[k] == min_count]
                            for lru_key in lru_keys:
                                if self.access_count[lru_key] == min_count:
                                    self.keys[lru_key].remove(lru_key)
                                    if not self.keys[lru_key]:
                                        del self.keys[lru_key]
                if key not in self.cache:
                    self.cache[key] = func(*args, **kwargs)
                return self.cache[key]
            return wrapper

    return LFUCache(maxsize, typed).__call__

