        """Get error indices corresponding to a coordinate."""

        if not isinstance(coord_name, str):
            raise TypeError("coord_name must be a string")

        if coord_name not in self._coords:
            raise KeyError(f"Coordinate '{coord_name}' not found")

        err_indices = []
        for i, coord in enumerate(self._coords[coord_name]):
            if coord.err:
                err_indices.append(i)

        return err_indices

