def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Verify that all digests in the manifest_files are present in the digests_used dictionary
    for file, digest in manifest_files.items():
        if digest not in digests_used:
            raise MissingDigestError(f"Digest for file '{file}' is missing in digests_used")

    # Verify that all digests used in the digests_used dictionary are present in the manifest_files
    for digest in digests_used.values():
        if digest not in manifest_files.values():
            raise UnusedDigestError(f"Digest '{digest}' is unused in manifest_files")

    # If all checks pass, return True
    return True

