def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    fixity_files = fixity.get('files', [])

    if not isinstance(fixity_files, list):
        raise ValueError("'files' key in fixity block must be a list")

    for manifest_file in manifest_files:
        if not isinstance(manifest_file, dict):
            raise ValueError("Each manifest file must be a dictionary")

        manifest_file_path = manifest_file.get('path')

        if not manifest_file_path:
            raise ValueError("Manifest file must contain a 'path' key")

        if manifest_file_path not in fixity_files:
            raise ValueError(f"File {manifest_file_path} is not referenced in the fixity block")

    for fixity_file in fixity_files:
        if fixity_file not in [f['path'] for f in manifest_files]:
            raise ValueError(f"File {fixity_file} in fixity block is not listed in the manifest files")

