def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    combined = {}
    for d in dicts:
        for key, value in d.items():
            if key in combined:
                combined[key] += value
            else:
                combined[key] = value
    return combined

