def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    if isinstance(commands, str):
        commands = [commands]

    for cmd in commands:
        cmd_with_args = [cmd] + args

        try:
            if hide_stderr:
                process = subprocess.Popen(cmd_with_args, cwd=cwd, env=env, stderr=subprocess.DEVNULL)
            else:
                process = subprocess.Popen(cmd_with_args, cwd=cwd, env=env)

            if verbose:
                print(f"Running command: {' '.join(cmd_with_args)}")

            process.wait()

            if verbose:
                print(f"Command {' '.join(cmd_with_args)} completed with return code {process.returncode}")

            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, cmd_with_args)

        except FileNotFoundError as e:
            print(f"Error: Command not found: {cmd_with_args}")
            raise e
        except Exception as e:
            print(f"Error running command: {' '.join(cmd_with_args)}")
            raise e

