def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """

    import os
    import json
    import logging
    from typing import Dict, List, Tuple

    config_dict = {}
    log_records: List[logging.LogRecord] = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config_data = file.read()
                if resolve_env:
                    config_data = os.path.expandvars(config_data)
                parsed_config = json.loads(config_data)
                config_dict[config_filename] = parsed_config
        except FileNotFoundError as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, str(e), (), None))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, str(e), (), None))
        except Exception as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, str(e), (), None))

    # Apply overrides if provided
    if overrides:
        for config_filename, config in config_dict.items():
            config.update(overrides)

    return config_dict, log_records

