def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, abc.ABCMeta):
        raise ValueError("The first argument must be an ABCMeta object.")
    if not isinstance(candidate, type):
        raise ValueError("The second argument must be a type.")

    try:
        next(iface.__subclasses__())
    except StopIteration:
        return False

    if tentative:
        return issubclass(candidate, iface)

    return iface.register(candidate) is candidate

