def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check for explicit metaclass
    if explicit_mc is not None:
        return explicit_mc

    # Check for metaclass in bases
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # Determine default metaclass
    for base in bases:
        if isinstance(base, type):
            return type

    # Raise an error if no appropriate metaclass is found
    raise TypeError("Unable to determine metaclass for given bases")

