    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    if not parser_name or not isinstance(parser_name, str):
        raise ValueError("parser_name must be a non-empty string")

    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    # Define type casting rules based on parser_name
    type_casting_rules = {
        "main": {
            "arg1": int,
            "arg2": float,
        },
        "virsh": {
            "domain": str,
            "id": int,
        },
        "ospd": {
            "port": int,
            "timeout": float,
        }
    }

    for key, value in list(values_dict.items()):
        if key not in type_casting_rules[parser_name]:
            continue

        cast_type = type_casting_rules[parser_name][key]
        try:
            values_dict[key] = cast_type(value)
        except ValueError:
            del values_dict[key]

